using GraphApi.Models.FNZ.Transacciones;namespace GraphApi.Services.FNZ.Transacciones{    /// <summary>    /// Define las operaciones de negocio y persistencia para Transacciones.    /// </summary>    public interface ITransaccionesService    {        /// <summary>        /// Obtiene la lista de Transacciones con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadTransacciones>> GetTransacciones(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de Transacciones con filtros opcionales.        /// </summary>        /// <param name="transaccionID">Filtro opcional para TransaccionID.</param>        /// <param name="cuentaID">Filtro opcional para CuentaID.</param>        /// <param name="cuenta">Filtro opcional para Cuenta.</param>        /// <param name="tipoCuenta">Filtro opcional para TipoCuenta.</param>        /// <param name="usuarioID">Filtro opcional para UsuarioID.</param>        /// <param name="nombreUsuario">Filtro opcional para NombreUsuario.</param>        /// <param name="tipoMovimientoID">Filtro opcional para TipoMovimientoID.</param>        /// <param name="tipoMovimiento">Filtro opcional para TipoMovimiento.</param>        /// <param name="cargo">Filtro opcional para Cargo.</param>        /// <param name="abono">Filtro opcional para Abono.</param>        /// <param name="motivo">Filtro opcional para Motivo.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetTransaccionesDynamic(            int? transaccionID,            int? cuentaID,            string? cuenta,            string? tipoCuenta,            int? usuarioID,            string? nombreUsuario,            int? tipoMovimientoID,            string? tipoMovimiento,            decimal? cargo,            decimal? abono,            string? motivo,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo Transaccione.        /// </summary>        /// <param name="objInput">Datos para crear el Transaccione.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTransacciones> CreateTransacciones(            clCreateTransacciones objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un Transaccione.        /// </summary>        /// <param name="objInput">Datos para actualizar el Transaccione, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadTransacciones?> UpdateTransacciones(            clUpdateTransacciones objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un Transaccione por su ID.        /// </summary>        /// <param name="nTransaccionesID">ID del Transaccione a eliminar.</param>        Task<bool> DeleteTransacciones(int nTransaccionesID);    }}